def _path_var_value(ctx: ProfileExecutionContext, name: str) -> str:
    if name == "quest":
        return ctx.quest_rel
    if name == "project":
        return ctx.project_rel
    if name == "machine":
        return ctx.machine_rel
    if name == "active_child":
